<?php
require __DIR__.'/_common.php'; api_method_get();
$page=max(1,(int)($_GET['page']??1));$limit=max(1,min(50,(int)($_GET['limit']??10)));$offset=($page-1)*$limit;
if($offset>1000000)api_out(['error'=>['code'=>'invalid_page','message'=>'Page is too large.']],400);
$lang=(string)($_GET['lang']??'id');if(!in_array($lang,['id','en','es','fr','ja'],true))api_out(['error'=>['code'=>'invalid_language','message'=>'Supported languages: id, en, es, fr, ja.']],400);
try{
 if($lang==='id'){$count=(int)$pdo->query("SELECT COUNT(*) FROM posts WHERE status='published' AND (published_at IS NULL OR published_at<=NOW())")->fetchColumn();$q=$pdo->prepare("SELECT p.id,p.title,p.slug,p.excerpt,p.cover_image,p.published_at,p.updated_at,u.name author FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) ORDER BY COALESCE(p.published_at,p.created_at) DESC,p.id DESC LIMIT ? OFFSET ?");$q->bindValue(1,$limit,PDO::PARAM_INT);$q->bindValue(2,$offset,PDO::PARAM_INT);$q->execute();$items=$q->fetchAll();}
 else{$pdo->exec("CREATE TABLE IF NOT EXISTS post_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id INT UNSIGNED NOT NULL, language_code VARCHAR(5) NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL, excerpt TEXT NULL, seo_title VARCHAR(220) NULL, seo_description VARCHAR(320) NULL, content LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_post_translation(post_id,language_code), UNIQUE KEY uq_translation_slug(language_code,slug), INDEX idx_translation_language_status(language_code,status), CONSTRAINT fk_translation_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$c=$pdo->prepare("SELECT COUNT(*) FROM post_translations t JOIN posts p ON p.id=t.post_id WHERE t.language_code=? AND t.status='published' AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW())");$c->execute([$lang]);$count=(int)$c->fetchColumn();$q=$pdo->prepare("SELECT p.id,t.title,t.slug,t.excerpt,p.cover_image,p.published_at,t.updated_at,u.name author,t.language_code FROM post_translations t JOIN posts p ON p.id=t.post_id LEFT JOIN users u ON u.id=p.author_id WHERE t.language_code=? AND t.status='published' AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) ORDER BY COALESCE(p.published_at,p.created_at) DESC,p.id DESC LIMIT ? OFFSET ?");$q->bindValue(1,$lang);$q->bindValue(2,$limit,PDO::PARAM_INT);$q->bindValue(3,$offset,PDO::PARAM_INT);$q->execute();$items=$q->fetchAll();}
 api_out(['data'=>$items,'meta'=>['api_version'=>'1','page'=>$page,'limit'=>$limit,'total'=>$count,'total_pages'=>(int)ceil($count/$limit),'language'=>$lang]]);
}catch(Throwable $e){error_log('NOWRD API posts failed: '.$e->getMessage());api_out(['error'=>['code'=>'server_error','message'=>'Unable to retrieve posts.']],500);}
